import{_ as o}from"./chunks/analytics_hosting.D4xMhqgc.js";import{_ as t,c as s,b as a,a2 as r}from"./chunks/framework.BEqfOpL-.js";const n="/images/analytics_hosting_episodes.webp",i="/images/analytics_hosting_audience.webp",l="/images/analytics_buzzsprout.webp",f=JSON.parse('{"title":"Hosting platform analytics","description":"Hosting analytics brings downloads from Spreaker, Buzzsprout, Simplecast, Captivate, Transistor or Podigee into PodSEO. Use it to follow downloads across listening apps, compare episode launches and explore the audience breakdowns your host supplies (Transistor supplies downloads only; Podigee downloads and listening apps). A download is not the same as a completed listen or a unique person.","frontmatter":{},"headers":[],"relativePath":"features/hosting-analytics.md","filePath":"features/hosting-analytics.md"}'),d={name:"features/hosting-analytics.md"};function p(c,e,h,g,u,m){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="hosting-platform-analytics" tabindex="-1">Hosting platform analytics <a class="header-anchor" href="#hosting-platform-analytics" aria-label="Permalink to &quot;Hosting platform analytics&quot;">​</a></h1><p>Hosting analytics brings downloads from <strong>Spreaker</strong>, <strong>Buzzsprout</strong>, <strong>Simplecast</strong>, <strong>Captivate</strong>, <strong>Transistor</strong> or <strong>Podigee</strong> into PodSEO. Use it to follow downloads across listening apps, compare episode launches and explore the audience breakdowns your host supplies (Transistor supplies downloads only; Podigee downloads and listening apps). A download is not the same as a completed listen or a unique person.</p><p><strong>To access:</strong> choose your podcast → <strong>Analytics</strong>, then select your host&#39;s name in the source bar. The tab is called <strong>Spreaker</strong>, <strong>Buzzsprout</strong>, <strong>Simplecast</strong>, <strong>Captivate</strong>, <strong>Transistor</strong> or <strong>Podigee</strong>, rather than “Hosting platform”. It appears for supported feeds. For setup, follow <a href="/features/analytics-connections.html#hosting-spreaker-buzzsprout-simplecast-captivate-transistor-and-podigee">Connect your hosting platform</a>.</p><p><a href="/images/analytics_hosting.webp" title="Open screenshot at full size"><img src="'+o+'" alt="Hosting overview with downloads and period controls"></a></p><h2 id="read-overview" tabindex="-1">Read Overview <a class="header-anchor" href="#read-overview" aria-label="Permalink to &quot;Read Overview&quot;">​</a></h2><p>Choose <strong>30</strong>, <strong>90</strong> or <strong>365 days</strong>. The headline downloads, daily average, best day and chart follow that period. The page labels the source and latest update; read a failed-update or incomplete-coverage notice before interpreting missing data.</p><p>Spreaker and Simplecast can also provide weekly unique-listener measurements (Simplecast when your Simplecast plan includes them). Buzzsprout, Captivate, Transistor and Podigee weekly unique listeners are not shown. Do not add weekly unique listeners together or compare them directly with download totals.</p><h2 id="compare-episode-launches" tabindex="-1">Compare episode launches <a class="header-anchor" href="#compare-episode-launches" aria-label="Permalink to &quot;Compare episode launches&quot;">​</a></h2><ol><li>Open <strong>Episodes</strong>.</li><li>Enter a title in <strong>Search episodes</strong> and click <strong>Search</strong> to narrow the list.</li><li>On desktop, click <strong>Episode</strong> for newest-first ordering or the <strong>Last … days</strong> heading for downloads in the chosen period. On mobile, use <strong>Newest</strong> or <strong>Most downloads</strong>.</li><li>Compare <strong>First 7 days</strong>, <strong>First 30 days</strong>, the selected-period downloads and <strong>Total</strong> as separate windows.</li></ol><p><a href="/images/analytics_hosting_episodes.webp" title="Open screenshot at full size"><img src="'+n+'" alt="Hosting episode downloads and first-week comparisons"></a></p><p>First-days downloads count calendar days from publication. “–” can mean the episode is too young or the complete daily coverage is unavailable. <strong>n/a</strong> means its release predates the history the host provides, or the host supplies no daily measurements for it. Neither is zero. Read <strong>counted since</strong> and the explanatory note above the table.</p><p><strong>Total</strong> describes the episode total the host supplies; it need not match the sum of the visible daily history. A deleted or unavailable episode can also leave a gap between the catalog you see and host-level totals.</p><p>Where the host supplies an episode breakdown, expand <strong>Who listened to this episode</strong> for the available geography, apps or devices. These describe the stated episode window; they do not inherit every page-level period choice.</p><h2 id="understand-audience" tabindex="-1">Understand Audience <a class="header-anchor" href="#understand-audience" aria-label="Permalink to &quot;Understand Audience&quot;">​</a></h2><p>Open <strong>Audience</strong> to see <strong>Who listens</strong>. Cards can show apps, devices, operating systems and countries. They describe the host&#39;s reported window, typically the last 30 days, and <strong>do not follow the 30 / 90 / 365 days selector</strong>. Read the dates below each card. Where a country map is available, expand <strong>All reported countries</strong> and select a country to highlight it and read its reported share.</p><p><a href="/images/analytics_hosting_audience.webp" title="Open screenshot at full size"><img src="'+i+'" alt="Host audience cards and their reporting windows"></a></p><p>Spreaker and Simplecast breakdowns can depend on the plan you hold with them. A message about an unavailable breakdown refers to the host&#39;s access, not necessarily your PodSEO plan. Buzzsprout can provide episode-level and historical app/download reports with their own metric selectors and dates.</p><p><a href="/images/analytics_buzzsprout.webp" title="Open screenshot at full size"><img src="'+l+'" alt="Buzzsprout audience history and report controls"></a></p><p>Where provided, <strong>Reported values</strong> and <strong>Export CSV</strong> let you inspect a report&#39;s observations. “Web browsers” may include automated downloads; a browser entry is not proof of a human listener. A previous report shown after a failed refresh should be read using its original date.</p><h2 id="compare-with-your-other-sources" tabindex="-1">Compare with your other sources <a class="header-anchor" href="#compare-with-your-other-sources" aria-label="Permalink to &quot;Compare with your other sources&quot;">​</a></h2><p>Use <a href="/features/analytics.html#compare-the-same-episode-across-platforms">Analytics → Overview → Across platforms</a> to select the same episode and inspect its host downloads alongside the available Apple, Spotify and YouTube measurements. Keep every source separate: the same download may already be included in your host and in a tracking prefix.</p><p>If your host is not supported, <a href="/features/hopr-fm-analytics.html">hopr.fm</a> or <a href="/features/op3-analytics.html">OP3</a> can provide download measurements when your feed supports their prefix. They start from the traffic they observe; they do not reconstruct your host&#39;s earlier download history.</p><h2 id="connection-problems" tabindex="-1">Connection problems <a class="header-anchor" href="#connection-problems" aria-label="Permalink to &quot;Connection problems&quot;">​</a></h2><p>A newly connected show can display the overview before the episode history is ready. A <strong>Connection expired</strong> message asks you to reconnect; older numbers, where shown, retain their original dates. Use <a href="/features/connections.html">Connections</a> to manage access. For Buzzsprout, Simplecast, Captivate, Transistor and Podigee, deleting access in PodSEO does not invalidate the token at your host: delete or regenerate it in Buzzsprout, regenerate it in Simplecast&#39;s <strong>Private Apps</strong>, click <strong>Regenerate API Key</strong> in Captivate, click <strong>Expire API Key</strong> in Transistor&#39;s <strong>Manage Your Account</strong>, or click <strong>Remove</strong> next to the token in Podigee&#39;s <strong>Data &amp; integrations</strong> → <strong>API keys</strong>, if you need to revoke it completely.</p>',24)])])}const b=t(d,[["render",p]]);export{f as __pageData,b as default};
